def get_database_stats(db_path: str) -> Dict[str, Any]:
    """
    Get comprehensive statistics about the stock database.
    
    Args:
        db_path (str): Connection string or path for the PostgreSQL database
        
    Returns:
        Dict[str, Any]: Database statistics and information
    """
    try:
        engine = get_engine(db_path)
        
        stats = {
            "database_info": {
                "url": engine.url.render_as_string(hide_password=True),
                "type": "PostgreSQL"
            },
            "tables": {},
            "stock_data": {}
        }
        
        with engine.connect() as conn:
            # Get table information from information_schema
            tables_result = conn.execute(text("SELECT table_name FROM information_schema.tables WHERE table_schema='public'"))
            tables = [row[0] for row in tables_result]
            
            for table_name in tables:
                row_count = conn.execute(text(f'SELECT COUNT(*) FROM "{table_name}"')).scalar()
                stats["tables"][table_name] = {
                    "row_count": row_count
                }
            
            # Get stock-specific statistics
            if "stocks" in tables:
                total_records = conn.execute(text("SELECT COUNT(*) FROM stocks")).scalar()
                unique_tickers = conn.execute(text("SELECT COUNT(DISTINCT ticker) FROM stocks")).scalar()
                
                # Date range
                date_range_result = conn.execute(text("SELECT MIN(date), MAX(date) FROM stocks")).fetchone()
                
                # Records per ticker
                ticker_stats_result = conn.execute(text("""
                    SELECT ticker, COUNT(*) as count, MIN(date) as first_date, MAX(date) as last_date
                    FROM stocks 
                    GROUP BY ticker 
                    ORDER BY count DESC
                """))
                ticker_stats = ticker_stats_result.fetchall()
                
                stats["stock_data"] = {
                    "total_records": total_records,
                    "unique_tickers": unique_tickers,
                    "date_range": {
                        "earliest": str(date_range_result[0]) if date_range_result[0] else None,
                        "latest": str(date_range_result[1]) if date_range_result[1] else None
                    },
                    "ticker_breakdown": [
                        {
                            "ticker": row[0],
                            "record_count": row[1],
                            "first_date": str(row[2]) if row[2] else None,
                            "last_date": str(row[3]) if row[3] else None
                        }
                        for row in ticker_stats
                    ]
                }
        
        return {
            "success": True,
            "message": "Database statistics retrieved successfully",
            "data": stats
        }
        
    except Exception as e:
        return {
            "success": False,
            "message": f"Error retrieving database statistics: {str(e)}",
            "data": None
        }